import { readFileSync, writeFileSync, mkdtempSync, rmSync } from "fs";
import { tmpdir } from "os";
import { join } from "path";

// Replicate logic from json-validate.ts for isolated testing
const MODE_RANK: Record<string, number> = { advisory: 1, strict: 2, locked: 3 };
const MODE_KEYS = ["develop_enforcement_mode", "runtime_enforcement_mode"];

function tolerantParse(text: string): any {
  return JSON.parse(text);
}

function detectModeDowngrade(newContent: string, filePath: string): string | null {
  let currentContent: string;
  try {
    currentContent = readFileSync(filePath, "utf8");
  } catch {
    return null;
  }
  let current: any;
  let next: any;
  try {
    current = tolerantParse(currentContent);
    next = tolerantParse(newContent);
  } catch {
    return null;
  }
  for (const key of MODE_KEYS) {
    const from = current?.template_resolution?.[key] || "advisory";
    const to = next?.template_resolution?.[key] || "advisory";
    if (from === to) continue;
    if (MODE_RANK[to] < MODE_RANK[from] && (from === "strict" || from === "locked")) {
      return `${key} downgrade: ${from} → ${to}`;
    }
  }
  return null;
}

const dir = mkdtempSync(join(tmpdir(), "p1-5-test-"));
const file = join(dir, "project.config.json");

function test(name: string, current: any, next: any, expectBlocked: boolean) {
  writeFileSync(file, JSON.stringify(current));
  const result = detectModeDowngrade(JSON.stringify(next), file);
  const blocked = result !== null;
  const status = blocked === expectBlocked ? "PASS" : "FAIL";
  console.log(`${status}: ${name} | blocked=${blocked}${result ? " (" + result + ")" : ""}`);
}

const base = { project: { name: "x" }, template_resolution: {} };

test("strict → advisory", { ...base, template_resolution: { develop_enforcement_mode: "strict" } }, { ...base, template_resolution: { develop_enforcement_mode: "advisory" } }, true);
test("locked → strict", { ...base, template_resolution: { develop_enforcement_mode: "locked" } }, { ...base, template_resolution: { develop_enforcement_mode: "strict" } }, true);
test("locked → advisory", { ...base, template_resolution: { develop_enforcement_mode: "locked" } }, { ...base, template_resolution: { develop_enforcement_mode: "advisory" } }, true);
test("advisory → strict", { ...base, template_resolution: { develop_enforcement_mode: "advisory" } }, { ...base, template_resolution: { develop_enforcement_mode: "strict" } }, false);
test("strict → locked", { ...base, template_resolution: { develop_enforcement_mode: "strict" } }, { ...base, template_resolution: { develop_enforcement_mode: "locked" } }, false);
test("strict unchanged", { ...base, template_resolution: { develop_enforcement_mode: "strict" } }, { ...base, template_resolution: { develop_enforcement_mode: "strict" } }, false);
test("key removed from strict", { ...base, template_resolution: { develop_enforcement_mode: "strict" } }, { ...base, template_resolution: {} }, true);
test("new file no current", base, { ...base, template_resolution: { develop_enforcement_mode: "advisory" } }, false);

rmSync(dir, { recursive: true, force: true });
